import { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { fetchParkLots } from '../carApi';
import { calculateRecommendedPrice, formatPriceVN } from '../utils';

const RegisterCarStep2 = () => {
    const { t } = useTranslation();
    const navigate = useNavigate();
    const [formData, setFormData] = useState({
        dailyPrice: '10.000',
        currency: 'VND',
        address: '',
        parkLotId: '',
        rentalTerms: ''
    });
    const [isDropdownOpen, setIsDropdownOpen] = useState(false);
    const [isParkLotDropdownOpen, setIsParkLotDropdownOpen] = useState(false);
    const [parkLots, setParkLots] = useState([]);
    const [filteredParkLots, setFilteredParkLots] = useState([]);
    const [searchQuery, setSearchQuery] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [carInfo, setCarInfo] = useState(null);
    const [recommendedPriceRange, setRecommendedPriceRange] = useState(null);
    const searchInputRef = useRef(null);

    // Load saved data from localStorage on mount
    useEffect(() => {
        const savedData = localStorage.getItem('carRegistrationStep2');
        if (savedData) {
            const parsedData = JSON.parse(savedData);
            // Convert dailyPrice from number to formatted string if needed
            if (typeof parsedData.dailyPrice === 'number') {
                parsedData.dailyPrice = parsedData.dailyPrice.toLocaleString('de-DE');
            }
            setFormData(parsedData);
        }

        // Load car info from step 1
        const step1Data = localStorage.getItem('carRegistrationStep1');
        if (step1Data) {
            const carData = JSON.parse(step1Data);
            setCarInfo(carData);
            const priceRange = calculateRecommendedPrice(carData);
            if (priceRange) {
                setRecommendedPriceRange(priceRange);
                
                // Set the recommended price as default if no price is set
                if (!formData.dailyPrice || formData.dailyPrice === '10.000') {
                    setFormData(prev => ({
                        ...prev,
                        dailyPrice: formatPriceVN(priceRange.recommended)
                    }));
                }
            }
        }
    }, []);

    // const currencies = [
    //     { value: 'VND', label: 'VND' },
    //     { value: 'USD', label: 'USD' },
    //     { value: 'EUR', label: 'EUR' }
    // ];

    useEffect(() => {
        loadParkLots();
    }, []);

    useEffect(() => {
        if (isParkLotDropdownOpen && searchInputRef.current) {
            searchInputRef.current.focus();
        }
    }, [isParkLotDropdownOpen]);

    useEffect(() => {
        if (searchQuery.trim() === '') {
            setFilteredParkLots(parkLots);
        } else {
            const filtered = parkLots.filter(lot =>
                lot.name.toLowerCase().includes(searchQuery.toLowerCase())
            );
            setFilteredParkLots(filtered);
        }
    }, [searchQuery, parkLots]);

    const loadParkLots = async () => {
        setIsLoading(true);
        try {
            const data = await fetchParkLots();
            setParkLots(data);
            setFilteredParkLots(data);
        } catch (error) {
            console.error('Error loading park lots:', error);
        } finally {
            setIsLoading(false);
        }
    };

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({
            ...prev,
            [name]: value
        }));
    };

    const handleCurrencySelect = (currency) => {
        setFormData(prev => ({
            ...prev,
            currency: currency
        }));
        setIsDropdownOpen(false);
    };

    const handleParkLotSelect = (parkLot) => {
        // console.log('Selected parkLot:', parkLot);
        setFormData(prev => ({
            ...prev,
            address: parkLot.name,
            parkLotId: parkLot.managerId || parkLot.id // Use managerId if available, fallback to id
        }));
        setIsParkLotDropdownOpen(false);
        setSearchQuery('');
    };

    const handleSearchChange = (e) => {
        setSearchQuery(e.target.value);
    };

    const handleUseRecommendedPrice = () => {
        if (recommendedPriceRange) {
            setFormData(prev => ({
                ...prev,
                dailyPrice: formatPriceVN(recommendedPriceRange.recommended)
            }));
        }
    };

    const handleReturn = () => {
        navigate('/owner/register_car');
    };

    const handleNext = () => {
        // Save form data to localStorage before navigating
        // Convert dailyPrice from formatted string to number (e.g., "10.000" -> 10000)
        const dailyPriceValue = typeof formData.dailyPrice === 'string' 
            ? parseFloat(formData.dailyPrice.replace(/\./g, '')) || 0
            : formData.dailyPrice;
        
        const dataToSave = {
            ...formData,
            dailyPrice: dailyPriceValue
        };
        localStorage.setItem('carRegistrationStep2', JSON.stringify(dataToSave));
        navigate('/owner/register_car/step3');
    };

    return (
        <div className="min-h-screen bg-gray-50 py-8">
            <div className="max-w-2xl mx-auto px-4">
                {/* Header */}
                <div className="text-center mb-8">
                    <h1 className="text-xl font-semibold text-gray-900">{t('registerCar')}</h1>
                </div>

                {/* Progress Steps */}
                <div className="flex items-center justify-center mb-12">
                    <div className="flex items-center">
                        <div className="w-10 h-10 bg-gray-200 text-gray-500 rounded-full flex items-center justify-center font-medium">
                            1
                        </div>
                        <div className="w-8 h-0.5 bg-gray-300 mx-2"></div>
                        <div className="w-10 h-10 bg-gray-900 text-white rounded-full flex items-center justify-center font-medium">
                            2
                        </div>
                        <div className="w-8 h-0.5 bg-gray-300 mx-2"></div>
                        <div className="w-10 h-10 bg-gray-200 text-gray-500 rounded-full flex items-center justify-center font-medium">
                            3
                        </div>
                    </div>
                </div>

                {/* Form */}
                <div className="bg-white rounded-lg shadow-sm p-8">
                    {/* Default Rental Price */}
                    <div className="mb-8">
                        <label className="block text-sm font-medium text-gray-900 mb-2">
                            {t('defaultRentalPrice')}
                        </label>
                        <p className="text-xs text-gray-500 mb-3">
                            {t('defaultRentalPriceDescription')}
                        </p>

                        {/* Recommended Price Range */}
                        {recommendedPriceRange && (
                            <div className="mb-4 p-4 bg-blue-50 border border-blue-200 rounded-lg">
                                <div className="flex items-center justify-between mb-2">
                                    <div className="flex items-center">
                                        <svg className="w-4 h-4 text-blue-500 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                                        </svg>
                                        <span className="text-sm font-medium text-blue-900">Recommended Price Range</span>
                                    </div>
                                    <button
                                        type="button"
                                        onClick={handleUseRecommendedPrice}
                                        className="text-xs px-2 py-1 bg-blue-600 text-white rounded hover:bg-blue-700 transition-colors"
                                    >
                                        Use Recommended
                                    </button>
                                </div>
                                <div className="text-sm text-blue-800">
                                    <p className="mb-1">
                                        <span className="font-medium">Car Type:</span> {recommendedPriceRange.carType}
                                        {carInfo && <span className="ml-2 text-blue-600">({carInfo.yearOfManufacture})</span>}
                                    </p>
                                    <p className="mb-1">
                                        <span className="font-medium">Suggested Range:</span> {formatPriceVN(recommendedPriceRange.min)} - {formatPriceVN(recommendedPriceRange.max)} VND/day
                                    </p>
                                    <p>
                                        <span className="font-medium">Recommended:</span> <span className="font-semibold text-blue-900">{formatPriceVN(recommendedPriceRange.recommended)} VND/day</span>
                                    </p>
                                </div>
                            </div>
                        )}
                        
                        <div className="flex gap-4">
                            <div className="flex-1">
                                <input
                                    type="text"
                                    name="dailyPrice"
                                    value={formData.dailyPrice}
                                    onChange={handleInputChange}
                                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                                    placeholder="10.000"
                                />
                            </div>
                            <div className="w-24 relative">
                                <div className="w-full px-4 py-3 rounded-lg bg-white text-left flex items-center justify-between">
                                    VND
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Vehicle Address */}
                    <div className="mb-8">
                        <label className="block text-sm font-medium text-gray-900 mb-2">
                            {t('vehicleAddress')}
                        </label>
                        <div className="relative">
                            <button
                                type="button"
                                onClick={() => setIsParkLotDropdownOpen(!isParkLotDropdownOpen)}
                                className="w-full px-4 py-3 pr-10 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent bg-white text-left"
                            >
                                <span className={formData.address ? 'text-gray-900' : 'text-gray-400'}>
                                    {formData.address || t('enterVehicleAddress')}
                                </span>
                            </button>
                            <div className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 pointer-events-none">
                                <svg 
                                    className={`w-4 h-4 transition-transform ${isParkLotDropdownOpen ? 'rotate-180' : ''}`} 
                                    fill="none" 
                                    stroke="currentColor" 
                                    viewBox="0 0 24 24"
                                >
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                                </svg>
                            </div>

                            {isParkLotDropdownOpen && (
                                <>
                                    <div 
                                        className="fixed inset-0 z-10" 
                                        onClick={() => {
                                            setIsParkLotDropdownOpen(false);
                                            setSearchQuery('');
                                        }}
                                    />
                                    <div className="absolute z-20 w-full mt-1 bg-white border border-gray-300 rounded-lg shadow-lg overflow-hidden">
                                        {/* Search Box */}
                                        <div className="p-3 border-b border-gray-200">
                                            <div className="relative">
                                                <input
                                                    ref={searchInputRef}
                                                    type="text"
                                                    value={searchQuery}
                                                    onChange={handleSearchChange}
                                                    className="w-full px-3 py-2 pl-9 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                                                    placeholder="Search parking lots..."
                                                    onClick={(e) => e.stopPropagation()}
                                                />
                                                <svg 
                                                    className="w-4 h-4 absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400"
                                                    fill="none" 
                                                    stroke="currentColor" 
                                                    viewBox="0 0 24 24"
                                                >
                                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                                                </svg>
                                            </div>
                                        </div>

                                        {/* Park Lot List */}
                                        <div className="max-h-60 overflow-y-auto">
                                            {isLoading ? (
                                                <div className="px-4 py-8 text-center text-gray-500">
                                                    Loading...
                                                </div>
                                            ) : filteredParkLots.length > 0 ? (
                                                filteredParkLots.map((parkLot) => (
                                                    <button
                                                        key={parkLot.id}
                                                        type="button"
                                                        onClick={() => handleParkLotSelect(parkLot)}
                                                        className={`w-full px-4 py-3 text-left hover:bg-gray-100 transition-colors ${
                                                            formData.address === parkLot.name ? 'bg-gray-50 text-gray-900 font-medium' : 'text-gray-700'
                                                        }`}
                                                    >
                                                        <div className="flex items-center">
                                                            <svg className="w-4 h-4 mr-2 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" />
                                                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" />
                                                            </svg>
                                                            {parkLot.name}
                                                        </div>
                                                    </button>
                                                ))
                                            ) : (
                                                <div className="px-4 py-8 text-center text-gray-500">
                                                    No parking lots found
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                </>
                            )}
                        </div>
                    </div>

                    {/* Rental Terms */}
                    <div className="mb-8">
                        <label className="block text-sm font-medium text-gray-900 mb-2">
                            {t('rentalTerms')}
                        </label>
                        <p className="text-xs text-gray-500 mb-3">
                            {t('rentalTermsDescription')}
                        </p>
                        <textarea
                            name="rentalTerms"
                            value={formData.rentalTerms}
                            onChange={handleInputChange}
                            rows={6}
                            className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent resize-none"
                            placeholder={t('enterRentalTerms')}
                        />
                    </div>

                    {/* Action Buttons */}
                    <div className="flex gap-4">
                        <button
                            onClick={handleReturn}
                            className="flex-1 px-6 py-3 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 font-medium"
                        >
                            {t('return')}
                        </button>
                        <button
                            onClick={handleNext}
                            className="flex-1 px-6 py-3 bg-gray-900 text-white rounded-lg hover:bg-gray-800 font-medium"
                        >
                            {t('next')}
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default RegisterCarStep2;